files.components/Cart.tsx:
import formatDate from '../lib/formatDate'

function plural(n: number, word: string) {
  return n === 1 ? word : word + 's'
}

export function Cart({ items, totalCents, updated }: { items: number; totalCents: number; updated: Date }) {
  return <p>{items} {plural(items, 'item')}, total {totalCents}, updated {formatDate(updated)}</p>
}

